GeoLocation.prototype.parseLocation=function()
{
    var location=this.textBox.value;
    if(location==Lang.CITY_STATE_COUNTRY)location="";
    this.City=this.State=this.Country=this.ZipCode="";
    var tokens=location.split(",");
    if(tokens.length==1)
    {
        this.City=this.State=this.Country="";
        if(!isNaN(tokens[0]))App.My.City=tokens[0];
        else App.My.ZipCode=tokens[0];App.My.Country="USA";
    }
    else if(tokens.length==4)
    {
        if(!isNaN(tokens[1]))
        {
            this.City=tokens[0];
            this.ZipCode=tokens[1];
            this.State=tokens[2];
            this.Country=tokens[3];
        }
        else
        {
            if(!isNaN(tokens[2]))
            {
                this.City=tokens[0];
                this.State=tokens[1];
                this.ZipCode=tokens[2];
                this.Country=tokens[3];
            }
            else
            {
                this.City=tokens[0];
                this.Country=tokens[3];
            }
        }
        
    }
    else
    {
        if(isNaN(tokens[0]))
        {
            this.City=tokens[0];
        }
        else
        {
            this.ZipCode=tokens[0];this.Country="USA";
        }
        if(tokens.length>0)
        {
            if(isNaN(tokens[1]))
            {
                if(tokens.length==2)
                {
                    if(this.Country=="USA")
                    {
                        this.State=tokens[1];
                    }
                    else{
                        this.State="";this.Country=tokens[1];
                    }
                }
                else
                {
                    this.State=tokens[1];
                    this.Country=tokens[2];
                }
            }
            else
            {
                this.ZipCode=tokens[1];
                if(tokens.length>2)
                {
                    if(this.Country=="USA"){
                        this.State=tokens[2];
                    }
                    else{
                        this.State="";this.Country=tokens[2];
                    }
                }
            }
        }
        else
        {
            this.State=this.Country="";
        }
    }
    this.City=$trim(this.City);
    this.State=$trim(this.State);
    this.Country=$trim(this.Country);
    this.ZipCode=$trim(this.ZipCode);
    if(this.City.length==0)return false;
    else return true;
}
